<?php
namespace Tests\Feature;
use App\Models\{User,Owner,Venue,GatewayAccount,CheckoutAttempt};use App\Services\{VenueSettings,BookingEngine};use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\{DB,Mail,Hash,Http,RateLimiter};use Illuminate\Support\Str;use Tests\TestCase;
class RecoveryCheckoutTest extends TestCase {
 use RefreshDatabase;
 private function owner():Owner{$u=User::factory()->create();return Owner::unguarded(fn()=>Owner::create(['user_id'=>$u->id,'name'=>'Owner','email'=>'owner'.Str::random(5).'@example.com','activated'=>true,'email_verified_at'=>now(),'password'=>'OriginalOwner123']));}
 private function venue(Owner $owner):Venue{return Venue::create(['owner_id'=>$owner->user_id,'owner_account_id'=>$owner->id,'name'=>'Jardín','slug'=>'jardin-'.Str::lower(Str::random(6)),'published'=>true,'settings'=>array_replace(VenueSettings::defaults(),['capacity'=>100,'open_hour'=>10,'close_hour'=>26,'prep_minutes'=>0,'clean_minutes'=>0,'included_hours'=>8,'weekday_price'=>150000,'weekend_price'=>150000,'holiday_price'=>150000,'extra_hour_price'=>0,'deposit_value'=>30])]);}
 private function input():array{return ['date'=>now('America/Mexico_City')->addMonth()->startOfWeek()->addDays(2)->format('Y-m-d'),'start'=>14,'hours'=>8,'guests'=>20,'policy_accepted'=>true];}
 private function recovery(User|Owner $u,bool $owner=false):string{config(['portal.kind'=>$owner?'owner':'client']);Mail::fake();$this->postJson('/api/password/forgot',['email'=>strtoupper($u->email)])->assertOk();$key=hash('sha256',($owner?'owner:':'client:').strtolower($u->email));$this->assertNotNull(DB::table('account_recovery_tokens')->where('key',$key)->first());return $key;}
 public function test_unknown_and_known_email_receive_same_response_without_leaking_token():void{$u=User::factory()->create();Mail::fake();$known=$this->postJson('/api/password/forgot',['email'=>$u->email])->assertOk()->json();$unknown=$this->postJson('/api/password/forgot',['email'=>'nobody@example.com'])->assertOk()->json();$this->assertSame($known,$unknown);$this->assertArrayNotHasKey('token',$known);$this->assertDatabaseCount('account_recovery_tokens',1);}
 public function test_reset_is_hashed_single_use_and_does_not_log_customer_in():void{$u=User::factory()->create();$key=$this->recovery($u);$token=Str::random(64);DB::table('account_recovery_tokens')->where('key',$key)->update(['token_hash'=>hash('sha256',$token)]);$d=['email'=>$u->email,'token'=>$token,'password'=>'NuevaPassword123','password_confirmation'=>'NuevaPassword123'];$this->postJson('/api/password/reset',$d)->assertOk();$this->assertTrue(Hash::check('NuevaPassword123',$u->fresh()->password));$this->assertNotNull($u->fresh()->password_reset_at);$this->assertGuest();$this->postJson('/api/password/reset',$d)->assertUnprocessable();}
 public function test_expired_token_and_wrong_portal_cannot_reset():void{$u=User::factory()->create();$key=$this->recovery($u);$token=Str::random(64);DB::table('account_recovery_tokens')->where('key',$key)->update(['token_hash'=>hash('sha256',$token),'created_at'=>now()->subMinutes(31)]);$d=['email'=>$u->email,'token'=>$token,'password'=>'NuevaPassword123','password_confirmation'=>'NuevaPassword123'];$this->postJson('/api/password/reset',$d)->assertUnprocessable();DB::table('account_recovery_tokens')->where('key',$key)->update(['created_at'=>now()]);config(['portal.kind'=>'owner']);$this->postJson('/api/password/reset',$d)->assertUnprocessable();}
 public function test_owner_recovery_does_not_change_same_email_customer():void{$o=$this->owner();$u=User::factory()->create(['email'=>$o->email,'password'=>'CustomerPassword123']);$key=$this->recovery($o,true);$token=Str::random(64);DB::table('account_recovery_tokens')->where('key',$key)->update(['token_hash'=>hash('sha256',$token)]);$this->postJson('/api/password/reset',['email'=>$o->email,'token'=>$token,'password'=>'NewOwnerPassword123','password_confirmation'=>'NewOwnerPassword123'])->assertOk();$this->assertTrue(Hash::check('NewOwnerPassword123',$o->fresh()->password));$this->assertTrue(Hash::check('CustomerPassword123',$u->fresh()->password));}
 public function test_forgot_is_throttled_per_address_and_does_not_rotate_token_on_repeat():void{$u=User::factory()->create();$key=$this->recovery($u);$before=DB::table('account_recovery_tokens')->where('key',$key)->value('token_hash');$this->postJson('/api/password/forgot',['email'=>$u->email])->assertOk();$this->assertSame($before,DB::table('account_recovery_tokens')->where('key',$key)->value('token_hash'));}
 public function test_old_session_is_invalidated_after_password_change():void{$u=User::factory()->create();$this->actingAs($u)->getJson('/api/me')->assertOk();$u->forceFill(['password_reset_at'=>now()])->save();$this->getJson('/api/me')->assertUnauthorized();}
 public function test_email_link_uses_configured_portal_not_request_host_and_log_mail_is_not_enabled_in_production():void{config(['mail.default'=>'log']);$this->withoutMiddleware(\Illuminate\Foundation\Http\Middleware\ValidateCsrfToken::class);$this->app->detectEnvironment(fn()=>'production');$this->postJson('/api/password/forgot',['email'=>'person@example.com'])->assertStatus(503);$this->assertDatabaseCount('account_recovery_tokens',0);}
 public function test_policy_is_required_and_stored_for_booking_and_payment():void{$o=$this->owner();$v=$this->venue($o);$u=User::factory()->create();$input=$this->input();unset($input['policy_accepted']);$this->actingAs($u)->postJson('/api/venues/'.$v->slug.'/bookings',$input)->assertUnprocessable();$b=$this->postJson('/api/venues/'.$v->slug.'/bookings',$this->input())->assertCreated()->json();$this->assertSame('2026-10-28',$b['quote']['reservation_policy']['version']);$this->postJson('/api/bookings/'.$b['id'].'/checkout',['provider'=>'paypal','purpose'=>'deposit'])->assertUnprocessable();}
 private function cardAttempt():array{$v=$this->venue($this->owner());$u=User::factory()->create();$b=app(BookingEngine::class)->reserve($v,$u->id,$this->input());$g=GatewayAccount::create(['venue_id'=>$v->id,'provider'=>'mercadopago','enabled'=>true,'sandbox'=>true,'credentials'=>['public_key'=>'TEST-public','access_token'=>'private-token','merchant_id'=>'12345','webhook_secret'=>'secret']]);$this->actingAs($u);$a=$this->postJson('/api/bookings/'.$b->id.'/checkout',['provider'=>'mercadopago','purpose'=>'deposit','policy_accepted'=>true])->assertOk()->assertJsonPath('checkout.mode','embedded')->json();return [$b,$g,$a];}
 public function test_embedded_card_uses_server_amount_and_verifies_payment_before_confirming():void{Http::preventStrayRequests();[$b,$g,$a]=$this->cardAttempt();Http::fake(['api.mercadopago.com/v1/payments'=>Http::response(['id'=>123]),'api.mercadopago.com/v1/payments/123'=>Http::response(['id'=>123,'status'=>'approved','live_mode'=>false,'external_reference'=>$a['id'],'transaction_amount'=>$a['amount']/100,'currency_id'=>'MXN','collector_id'=>12345])]);$this->postJson('/api/checkout/'.$a['id'].'/card',['token'=>'card-token','payment_method_id'=>'visa','installments'=>1,'transaction_amount'=>0.01,'payer'=>['email'=>'attacker@example.com']])->assertOk()->assertJsonPath('status','paid');Http::assertSent(fn($r)=>$r->url()==='https://api.mercadopago.com/v1/payments'&&$r['transaction_amount']===$a['amount']/100&&$r['payer']['email']===$b->user->email&&$r->header('X-Idempotency-Key')[0]===$a['id'].'-card');$this->assertSame('confirmed',$b->fresh()->status);$this->postJson('/api/checkout/'.$a['id'].'/card',['token'=>'second','payment_method_id'=>'visa','installments'=>1])->assertUnprocessable();Http::assertSentCount(2);}
 public function test_card_wrong_receiver_or_unknown_result_never_confirms_or_recharges():void{[$b,$g,$a]=$this->cardAttempt();Http::fake(['api.mercadopago.com/v1/payments'=>Http::response(['id'=>123]),'api.mercadopago.com/v1/payments/123'=>Http::response(['id'=>123,'status'=>'approved','live_mode'=>false,'external_reference'=>$a['id'],'transaction_amount'=>$a['amount']/100,'currency_id'=>'MXN','collector_id'=>999])]);$d=['token'=>'card-token','payment_method_id'=>'visa','installments'=>1];$this->postJson('/api/checkout/'.$a['id'].'/card',$d)->assertOk()->assertJsonPath('status','unknown');$this->assertSame('hold',$b->fresh()->status);$this->assertSame(0,$b->payments()->count());$this->postJson('/api/checkout/'.$a['id'].'/card',$d)->assertUnprocessable();Http::assertSentCount(2);}
 public function test_customer_sees_only_public_payment_keys_and_other_customer_cannot_submit_card():void{[$b,$g,$a]=$this->cardAttempt();$response=$this->getJson('/api/bookings/'.$b->id.'/payment-options')->assertOk()->getContent();$this->assertStringContainsString('TEST-public',$response);$this->assertStringNotContainsString('private-token',$response);$this->actingAs(User::factory()->create())->postJson('/api/checkout/'.$a['id'].'/card',[])->assertForbidden();}
 public function test_paypal_rejects_app_name_as_merchant_id():void{$o=$this->owner();$v=$this->venue($o);config(['portal.kind'=>'owner']);$this->actingAs($o,'owner')->putJson('/api/owner/venues/'.$v->slug.'/gateways/paypal',['enabled'=>true,'sandbox'=>true,'credentials'=>['client_id'=>'public','client_secret'=>'private','merchant_id'=>'paymenter','webhook_id'=>'webhook']])->assertUnprocessable();}
 public function test_paypal_embedded_order_is_created_by_server_with_same_verified_amount():void{$v=$this->venue($this->owner());$u=User::factory()->create();$b=app(BookingEngine::class)->reserve($v,$u->id,$this->input());GatewayAccount::create(['venue_id'=>$v->id,'provider'=>'paypal','enabled'=>true,'sandbox'=>true,'credentials'=>['client_id'=>'public','client_secret'=>'private','merchant_id'=>'ABC23456789DE','webhook_id'=>'webhook']]);Http::fake(['api-m.sandbox.paypal.com/v1/oauth2/token'=>Http::response(['access_token'=>'private-oauth']),'api-m.sandbox.paypal.com/v2/checkout/orders'=>Http::response(['id'=>'ORDER123','links'=>[['rel'=>'approve','href'=>'https://www.sandbox.paypal.com/checkoutnow?token=ORDER123']]])]);$a=$this->actingAs($u)->postJson('/api/bookings/'.$b->id.'/checkout',['provider'=>'paypal','purpose'=>'deposit','policy_accepted'=>true])->assertOk()->assertJsonPath('external_id','ORDER123')->assertJsonPath('sdk.client_id','public')->json();$this->assertNotNull(CheckoutAttempt::find($a['id'])->policy_acceptance);Http::assertSent(fn($r)=>str_ends_with($r->url(),'/v2/checkout/orders')&&$r['purchase_units'][0]['amount']['value']===number_format($b->deposit/100,2,'.',''));$this->assertSame(0,$b->payments()->count());}
 public function test_recovery_email_contains_only_configured_origin_and_hashed_token_is_stored():void{config(['portal.customer_url'=>'https://reservas.example.com']);$u=User::factory()->create();$link=null;Mail::shouldReceive('html')->once()->with(\Mockery::on(function($text)use(&$link){preg_match('~https://reservas\.example\.com/recuperar#restablecer=([A-Za-z0-9]{64})&correo=[^\s"<]+~',html_entity_decode($text),$match);$link=$match[0]??null;return $link!==null;}),\Mockery::type('callable'));$this->postJson('https://attacker.invalid/api/password/forgot',['email'=>$u->email])->assertOk();$this->assertNotNull($link);parse_str(parse_url($link,PHP_URL_FRAGMENT),$query);$hash=DB::table('account_recovery_tokens')->first()->token_hash;$this->assertNotSame($query['restablecer'],$hash);$this->assertSame(hash('sha256',$query['restablecer']),$hash);}
 public function test_new_login_after_reset_remains_valid_and_old_token_is_rejected_after_resend():void{$u=User::factory()->create(['password'=>'OldPassword123']);$key=$this->recovery($u);$token=Str::random(64);DB::table('account_recovery_tokens')->where('key',$key)->update(['token_hash'=>hash('sha256',$token)]);$this->postJson('/api/password/reset',['email'=>$u->email,'token'=>$token,'password'=>'NewPassword123','password_confirmation'=>'NewPassword123'])->assertOk();$this->postJson('/api/login',['email'=>$u->email,'password'=>'OldPassword123'])->assertUnprocessable();$this->postJson('/api/login',['email'=>$u->email,'password'=>'NewPassword123'])->assertOk();$this->getJson('/api/me')->assertOk()->assertJsonPath('user.id',$u->id);}
 public function test_recovery_page_does_not_leak_tokens_in_referrers_and_owner_does_not_load_payment_scripts():void{$this->get('/recuperar?restablecer='.str_repeat('a',64))->assertOk()->assertHeader('Referrer-Policy','no-referrer');config(['portal.kind'=>'owner']);$r=$this->get('/gestion');$this->assertStringNotContainsString('paypal.com',$r->headers->get('Content-Security-Policy'));}
 public function test_rejected_card_is_not_counted_as_money_and_attempt_can_be_replaced():void{[$b,$g,$a]=$this->cardAttempt();Http::fake(['api.mercadopago.com/v1/payments'=>Http::response(['id'=>123]),'api.mercadopago.com/v1/payments/123'=>Http::response(['id'=>123,'status'=>'rejected','live_mode'=>false,'external_reference'=>$a['id'],'transaction_amount'=>$a['amount']/100,'currency_id'=>'MXN','collector_id'=>12345])]);$this->postJson('/api/checkout/'.$a['id'].'/card',['token'=>'card-token','payment_method_id'=>'visa','installments'=>1])->assertOk()->assertJsonPath('status','failed');$this->assertSame(0,$b->payments()->count());$new=$this->postJson('/api/bookings/'.$b->id.'/checkout',['provider'=>'mercadopago','purpose'=>'deposit','policy_accepted'=>true])->assertOk()->json();$this->assertNotSame($a['id'],$new['id']);}

}
